import java.math.BigInteger

fun main() {
    val t = readln().toInt()
    repeat(t) {
        val n = readln().toInt()
        var s = BigInteger.ONE
        repeat(n - 1) {
            s = s.shiftLeft(1).add(BigInteger.ONE)
        }
        println(s)
    }
}

import java.math.BigInteger
import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val t = br.readLine()?.toIntOrNull() ?: 0
    repeat(t) {
        val n = br.readLine()?.toIntOrNull() ?: 0
        val result = BigInteger.ONE.shiftLeft(max(1, n)).subtract(BigInteger.ONE)
        println(result)
    }
}

